-- 지출 점검 2단계 준비. 운영에는 아직 실행하지 않음.
-- 먼저 card_ledger_v1.sql와 기존 app_settings·hub_ui_texts가 있어야 함.
-- 재실행해도 원장이 편집한 설정은 덮어쓰지 않음.
begin;
grant select on public.card_sms_failed_raw to authenticated;
do $$begin
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='card_sms_failed_raw' and policyname='card_sms_failed_raw_owner_read') then
  create policy card_sms_failed_raw_owner_read on public.card_sms_failed_raw for select to authenticated
   using(public.my_role()='owner' and expires_at>now());
 end if;
end$$;
on conflict(key) do nothing;
on conflict(key) do nothing;
commit;
